mapper.select:
WITH RECURSIVE dcr_tree(dcr01_class_tree_id, dcr01_company_id, dcr01_class_tree_nm, dcr01_parent_tree_id, depth, path, cycle) AS ( SELECT a.dcr01_class_tree_id, a.dcr01_company_id, a.dcr01_class_tree_nm, a.dcr01_parent_tree_id, 1, ARRAY[CAST(a.dcr01_parent_tree_id AS varchar) || LPAD(CAST(a.dcr01_seq AS varchar), 10, '0') || a.dcr01_class_tree_cd || a.dcr01_class_tree_id], false FROM dcr01_class_tree a WHERE a.dcr01_company_id = #{companyId} AND a.dcr01_parent_tree_id = 0 AND a.dcr01_use_yn = 'true' UNION ALL SELECT a.dcr01_class_tree_id, a.dcr01_company_id, a.dcr01_class_tree_nm, a.dcr01_parent_tree_id, b.depth + 1, array_append(b.path, CAST(a.dcr01_parent_tree_id AS varchar) || LPAD(CAST(a.dcr01_seq AS varchar), 10, '0') || a.dcr01_class_tree_cd || a.dcr01_class_tree_id), a.dcr01_class_tree_nm = any(b.path) FROM dcr01_class_tree a INNER JOIN dcr_tree b ON a.dcr01_parent_tree_id = b.dcr01_class_tree_id WHERE a.dcr01_company_id = #{companyId} AND a.dcr01_use_yn = 'true' AND NOT cycle ) SELECT a.dcr01_class_tree_id AS code , a.dcr01_class_tree_nm AS name FROM dcr_tree a INNER JOIN dcr03_org_auth b ON (dcr01_class_tree_id = dcr03_class_tree_id AND b.dcr03_org_code_id = #{orgId} AND COALESCE(dcr03_update_yn, 'false') = 'true') WHERE a.depth = #{level}
AND a.dcr01_parent_tree_id = #{dcrParentId}
ORDER BY path
